head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setRowNumVisible]<br/>GridView 컴포넌트의 rowNumVisible 속성을 설정합니다.",
    "validation" : [
        "visible 파라미터를 true 로 설정 시 Row 의 번호를 나타내는 Column 을 왼쪽 첫번째에 표시하여야 합니다.",
        "visible 파라미터를 false 로 설정 시 Row 의 번호를 나타내는 Column 을 표시하지 않아야 합니다.",
        "DrillDown 기능이나 필터로 화면에 표시되지 않는 Row 는 번호를 갖지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        rowNumVisible: true,
        rowNumHeaderValue: "No.",   
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList);
}



scwin.btn_setRowNumVisible_onclick = function () {
    let visible = par_visible.getText() === "true";
debugger;
    target1.setRowNumVisible(visible);
    wf_body_bottom.getObj("scwin").setReturnValue("setRowNumVisible(" + visible + ")");

    // getRowNumVisible 로 설정값 확인
    let rtn = target1.getRowNumVisible();
    wf_body_bottom.getObj("scwin").setReturnValue("getRowNumVisible() : " + rtn);
}
